@ParameterizedTest
@ValueSource(strings = { "?", "-help", "-h" })
void testUsageOptions(String option) {
    // invoke enhancer with a usage option
    InvocationResult result = invokeEnhancer(option);
    String outputString = result.getOutputString();
    String errorString = result.getErrorString();
    assertEquals(0, result.getExitValue(), "Wrong exit code from Enhancer with stderr:\n" + errorString);
    assertTrue(outputString.contains("javax.jdo.Enhancer"), "Expected Usage message from out:\n" + outputString + " with err:\n" + errorString);
}

@Test
void testInvalidOption() {
    // invoke enhancer with an invalid option
    InvocationResult result = invokeEnhancer("-poo");
    assertEquals(Constants.ENHANCER_USAGE_ERROR, result.getExitValue(), "Wrong return value ");
    String errorString = result.getErrorString();
    assertTrue(errorString.contains("javax.jdo.Enhancer"), "Expected Usage message from err:\n" + errorString);
}

@Test
void testProperties() {
    // invoke enhancer with verbose option
    InvocationResult result = invokeEnhancer("-v");
    String outputString = result.getOutputString();
    String errorString = result.getErrorString();
    assertEquals(0, result.getExitValue(), "Wrong exit code from Enhancer with stderr:\n" + errorString);
    assertTrue(outputString.contains(Constants.PROPERTY_ENHANCER_VENDOR_NAME), "Expected MockEnhancer vendor message from out:\n" + outputString + " with err:\n" + errorString);
    assertTrue(outputString.contains(Constants.PROPERTY_ENHANCER_VERSION_NUMBER), "Expected MockEnhancer version message from out:\n" + outputString + " with err:\n" + errorString);
    assertTrue(outputString.contains("Mock Enhancer"), "Expected MockEnhancer vendor message from out:\n" + outputString + " with err:\n" + errorString);
    assertTrue(outputString.contains("2.3.0"), "Expected MockEnhancer vendor message from out:\n" + outputString + " with err:\n" + errorString);
    assertTrue(outputString.contains("MockKey"), "Expected MockEnhancer properties message from out:\n" + outputString + " with err:\n" + errorString);
}

