    // 9a and 9b include services/javax.jdo.PersistenceManagerFactory
    // with bad implementations
    URLClassLoader loader = new JDOConfigTestClassLoader(getClass().getClassLoader(), JDOCONFIG_CLASSPATH_PREFIX + "/Negative09/9a/", JDOCONFIG_CLASSPATH_PREFIX + "/Negative09/9b/", TEST_CLASSPATH, API_CLASSPATH);
    JDOFatalException x = assertThrows(JDOFatalException.class, () -> JDOHelper.getPersistenceManagerFactory("name.negative09", loader), "JDOHelper failed to throw JDOFatalUserException");
    Throwable[] nestedExceptions = x.getNestedExceptions();
    if (nestedExceptions.length != 2) {
        appendMessage("JDOHelper.getPersistenceManagerFactory wrong number of " + "nested exceptions. Expected 2, got " + nestedExceptions.length + "\n" + x);
    }
    for (Throwable exception : nestedExceptions) {
        if (!(exception instanceof JDOFatalException)) {
            appendMessage("Nested exception " + exception.getClass().getName() + " is not a JDOFatalException.");
        }
    }
    failOnError();
}

