    assertFalse(JDOHelper.isDeleted(nbcpc2), "IsDeleted should be false before addStateInterrogations");
    addStateInterrogations();
    assertFalse(JDOHelper.isDeleted(Boolean.TRUE), "IsDeleted should be false for non-pc instances");
    implHelper.removeStateInterrogation(si2);
    assertFalse(JDOHelper.isDeleted(nbcpc2), "IsDeleted should be false after removeStateInterrogations");
}

